"""Fail-closed migration tests for historical description evidence."""from __future__ import annotationsfrom collections.abc import Iterablefrom pathlib import Pathfrom tests.description_cache_migration_fixture import (    write_legacy_inputs,)from gametool.description_cache import load_description_cachefrom gametool.description_cache_migration import (    DescriptionCacheMigrationOptions,    migrate_description_cache,)_LEGACY_CACHE_HEADER = (    "分类",    "基础ID",    "文本角色",    "等级/变体",    "原始全文",    "可读全文",    "来源地图SHA256",    "来源路径",)_LEGACY_DESCRIPTION_HEADER = (    "分类",    "对象ID",    "基础ID",    "名称",    "自定义",    "等级",    "原始提示",    "可读提示",    "提示来源",    "原始说明",    "可读说明",    "说明来源",    "完整性状态",)def test_migration_accepts_only_exact_base_client_fill(tmp_path: Path) -> None:    # Given: schema-1 state, schema-2 cache, and its exact base-client source row.    legacy_output, legacy_cache = write_legacy_inputs(tmp_path)    output = tmp_path / "trusted"    # When: the explicit migration proves and publishes the candidate.    result = migrate_description_cache(        DescriptionCacheMigrationOptions(legacy_output, legacy_cache, output)    )    # Then: exactly one manifest-bound base description is available.    assert result.accepted_count == 1    assert result.rejected_count == 0    cache = load_description_cache(str(output / "可信描述缓存.tsv"))    assert cache.lookup("物品", "ratf", "扩展提示", None)[0].raw_value == "原版说明"def _broken_tsv(_rows: Iterable[tuple[str, ...]]) -> str:    return "broken\n"